import { Bookmark } from "lucide-react";
import { cn } from "@/lib/utils";
import type { Opportunity } from "@/lib/types";

interface OpportunityCardProps {
  opportunity: Opportunity;
  className?: string;
}

export function OpportunityCard({ opportunity, className }: OpportunityCardProps) {
  const { title, location, badges, timeLabel, logoVariant } = opportunity;

  // Simulate generic logo color based on variant
  const getLogoBg = (variant: string) => {
    if (variant.includes("yellow")) return "bg-yellow-400 text-white";
    if (variant.includes("orange")) return "bg-orange-500 text-white";
    if (variant.includes("blue")) return "bg-blue-600 text-white";
    if (variant.includes("red")) return "bg-red-500 text-white";
    if (variant.includes("green")) return "bg-emerald-500 text-white";
    if (variant.includes("purple") || variant.includes("pink")) return "bg-purple-600 text-white";
    return "bg-slate-800 text-white";
  };

  return (
    <article
      className={cn(
        "group relative flex flex-col justify-between rounded-[20px] border border-slate-100 bg-white p-5",
        "transition-all duration-200 cursor-pointer",
        "hover:-translate-y-1 hover:border-slate-200 hover:shadow-lg",
        className
      )}
      tabIndex={0}
      aria-label={`${title} at ${location}`}
    >
      <div className="flex flex-col gap-4">
        {/* Header: Logo + Title */}
        <div className="flex items-start gap-3">
          <div className={cn("flex h-12 w-12 shrink-0 items-center justify-center rounded-xl font-bold text-lg", getLogoBg(logoVariant))}>
            {logoVariant.split("-")[1]?.charAt(0).toUpperCase() || title.charAt(0)}
          </div>
          <div className="flex flex-col mt-0.5">
            <h3 className="text-[14px] font-bold leading-snug text-slate-900 line-clamp-1">{title}</h3>
            <p className="mt-0.5 text-[12px] font-medium text-slate-500">{location}</p>
          </div>
        </div>

        {/* Badges */}
        {badges && badges.length > 0 && (
          <div className="flex flex-wrap gap-2">
            {badges.map((b) => (
              <span key={b} className="rounded-full bg-slate-50 px-2.5 py-1 text-[11px] font-semibold text-slate-600 border border-slate-100">
                {b}
              </span>
            ))}
          </div>
        )}
      </div>

      {/* Footer */}
      <div className="mt-6 flex items-center justify-between border-t border-slate-50 pt-4">
        <span className="text-[12px] font-medium text-slate-400">{timeLabel}</span>
        <button className="text-slate-400 transition-colors hover:text-slate-900" aria-label="Save opportunity">
          <Bookmark size={16} strokeWidth={2.5} />
        </button>
      </div>
    </article>
  );
}
